using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.SpectralGraph;

internal sealed class IdealIntersectionSpectralTransportDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/SpectralGraph/IdealIntersectionSpectralTransport.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/GraphInvariants/idealintersection2026sixsupport");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual ideal-intersection graph, its exact support cells, and complement/join spectral transport.",
        H("Actual ideals and six-support spectral transport"), Blocks(
            Paragraph(Text("The graph model and support decomposition are attributed to Haobo Ma, Reza Nikandish and Wenlin Zhang, paper/core/body.tex in the public manuscript the-omega-institute/ideal-intersection-laplacian at revision b93becea662a746badeadba42fdc3d3eb3db9382. These Lean proofs and this exposition are independently authored. The theorem is a prerequisite for the retained three-prime classification. It proves no endpoint obstruction, maximal-root estimate, finite exponent base or complete nonintegrality classification; the broader Question Q3 remains open.")),
            Paragraph(Text("The parameters are arbitrary injective prime data p on Fin 3 and arbitrary positive natural exponents k. Taking p=(p,q,r) and k=(a,b,c) gives the original modulus p^a q^b r^c. There is no ordering condition on either triple. All displayed statements are projected from the exact Lean declarations by the existing Scribe interface.")),
            Def("IdealVertex", "The actual carrier", "A vertex is an actual ideal of ZMod n, together with proofs that it is neither the bottom nor the top ideal. The carrier is defined before any exponent enumeration."),
            Def("idealGraph", "The actual ideal-intersection graph", "Two distinct actual ideals are adjacent precisely when their infimum is not the bottom ideal. Symmetry comes from commutativity of infimum and loops are excluded explicitly."),
            Def("Box", "The bounded exponent box", "The i-th exponent coordinate is Fin(k_i+1), so the endpoints zero and k_i are both included."),
            Def("primeProduct", "The modulus and divisor products", "The same product construction is used for the modulus with exponents k and for the generator with exponents alpha."),
            Def("divisorIdeal", "The actual principal ideal", "Map the integer ideal generated by the divisor through the surjective integer-cast homomorphism to ZMod n. The proof uses the kernel ideal generated by n; no ideal correspondence is assumed."),
            Def("coordinateIdeal", "The ideal of an exponent vector", "The ideal is generated by the reduction of the product of the three prime powers with the indicated exponents."),
            Def("zeroCoordinate", "The whole-ring endpoint", "All zero exponents represent the top ideal."),
            Def("lastCoordinate", "The zero-ideal endpoint", "All maximal exponents represent the bottom ideal."),
            Def("ExponentVertex", "Both exclusions", "Remove exactly the zero coordinate and the maximal coordinate from the box. The proofs retain both exclusions throughout the equivalence."),
            Def("idealEquiv", "Unique actual ideal enumeration", "Every integer ideal is principal. Applying this to the comap of an actual ideal produces a nonnegative divisor of the modulus. Prime factorization supplies its unique bounded exponent coordinates. Reverse divisibility gives the ideal order and proves uniqueness. The endpoint identities restrict the equivalence to exactly the actual vertices."),
            Def("support", "Support by nonmaximal exponents", "The support consists of those coordinates alpha_i strictly below k_i. It is nonempty on every vertex, and it is full at the excluded zero coordinate."),
            Thm("actual_adjacency", "Actual support adjacency", "The infimum of two coordinate ideals corresponds to coordinatewise maximum. Thus an intersection is nonzero precisely when some coordinate of both vectors is nonmaximal. The theorem retains distinctness as well as support overlap.", false),
            Def("properSupports", "The six original support cells", "The support order is 1,2,3,12,13,23, exactly the order of the existing literal complement quotient."),
            Def("actualSupport", "Support of an actual ideal", "Apply the inverse of the proved ideal equivalence and then the support map. No support assignment is supplied as an assumption."),
            Thm("proper_fiber_card", "The six actual fiber cardinalities", "For a proper nonempty support S, coordinates in S have exactly k_i choices and coordinates outside S are forced to equal k_i. Neither removed endpoint belongs to such a fiber. The six cardinalities are a,b,c,ab,ac,bc.", false),
            Thm("full_fiber_card", "The full-support cardinality", "Every coordinate in the full-support fiber is strictly below its maximum. The zero vector is removed and the maximal vector is already absent, giving abc-1 vertices. This count includes the empty full-support fiber when a=b=c=1.", false),
            Def("cellSizes", "Natural cell weights", "These are the six proved proper-support cardinalities in the existing quotient order."),
            Def("properOrder", "The order of H", "N=a+b+c+ab+ac+bc."),
            Def("universalOrder", "The universal-vertex count", "u=abc-1 as a natural number. The proof never assumes u positive."),
            Def("totalOrder", "The order of the actual graph", "V=N+u; the actual carrier count is proved by its partition into proper-support and full-support ideals."),
            Def("complementQuotient", "Reuse of the literal C", "This is the quotient definition from SixSupportLaplacianLowRoot at the three natural exponents cast to real numbers. The existing weighted left-kernel assertion in quotient_geometry is used directly in the eigenpair proof."),
            Def("intersectionQuotient", "The actual restriction B", "B=NI-1 w^T-C. Its action is proved to be the sum of w_j(v_i-v_j) over intersecting support cells. The actual H Laplacian is then proved to restrict to B."),
            Def("graphReindex", "All prime assignments and exponent permutations", "Reindex bounded coordinates by an arbitrary permutation and transport through the two proved actual ideal equivalences. Support overlap is preserved. The resulting graph isomorphism does not require the two rings to have the same modulus or the prime assignments to be the same."),
            Def("actualFintype", "The constructed finite carrier", "The actual ideal carrier is enumerated using the proved exponent equivalence. The actual graph operators carry this constructed finite instance explicitly; no finite enumeration or graph correspondence is assumed."),
            Def("HVertex", "Delete the full-support actual ideals", "H vertices remain actual ideal vertices; the additional predicate excludes precisely full support."),
            Def("HGraph", "The actual induced graph H", "Its edges are inherited directly from the actual ideal-intersection graph."),
            Def("cell", "The unique proper-support cell", "The six proper supports exhaust all nonempty nonfull subsets of the three coordinates. Their distinctness makes each actual H vertex have a unique cell number."),
            Def("cellEmbedding", "The injective cell-constant map", "A six-vector is pulled back along the actual cell map. Every cell has positive cardinality at positive exponents, so the cell map is surjective and the linear embedding is injective."),
            Def("FullVertex", "The actual universal summand", "This is the subtype of actual ideal vertices whose support is all three coordinates. Its cardinality is u, including zero."),
            Def("joinPartition", "Partition of the actual carrier", "An actual ideal lies in H or in the full-support subtype according to whether its support is nonfull or full. The inverse simply forgets the extra subtype proof."),
            Def("universalJoin", "The complete-graph join", "On H plus Fin u, retain the actual edges of H, make the Fin u summand complete, and include every edge between the two summands. Fin 0 gives the zero-universal-vertex case without a separate convention."),
            Def("universalJoinIso", "The actual K_u join H realization", "The full-support cardinality supplies an equivalence to Fin u. The carrier partition, full-support universality and actual H adjacency prove a graph isomorphism from this join to the original actual ideal graph."),
            Def("extendByZero", "A concrete function on actual ideal vertices", "At an H vertex use its cell-vector coordinate; at a full-support vertex use zero. A nonzero quotient vector remains nonzero because restriction to H is the injective cell-constant embedding."),
            Def("SpectralRealization", "The complete graph prerequisite", "The structure records the actual coordinate bijection, both vertex exclusions, infimum correspondence, support adjacency, all seven fiber counts, N and V, the empty universal boundary, the complete join isomorphism, the injective embedding, both actual Laplacian restrictions, reflection, nonzero H and actual-graph eigenpairs, nonintegral transfer and all prime/exponent permutations. Its fields introduce no graph-correspondence or spectral-lifting hypothesis."),
            Thm("spectral_realization", "Uniform actual-ideal spectral transport", "For Cv=mu v with v nonzero and mu different from zero, the reused weighted left-kernel relation gives sum_j w_j v_j=0. Reflection then gives Bv=(N-mu)v. The actual Laplacian restriction realizes this as an H eigenpair, and mu different from N makes the H eigenvalue nonzero. At an H vertex the zero extension gains u times its value; at a full-support vertex the actual Laplacian is minus the weighted sum, hence zero. The result is a nonzero actual graph eigenvector at V-mu. Since V is an integer, nonintegrality of mu implies nonintegrality of V-mu. The proof uses actual ideal fibers at every graph step and does not require the full-support type to be inhabited.", true),
            Paragraph(Text("The delivered low-root geometry remains the single source for the literal C and its weighted left kernel. This module adds the actual ideal carrier and its faithful realization; it does not repeat the low-root proof or introduce a generic certificate or spectral framework. The original positive finite exponent tables are absent. The endpoint, repeated-exponent, unit/small-minimum, spectral-order and maximal-root classification branches remain separate obligations."))
        )));

    private static DocumentBlock Def(string name, string title, string text) =>
        Node(name, title, text, DescribeRole.Definition, true);

    private static DocumentBlock Thm(string name, string title, string text, bool repoDerived) =>
        Node(name, title, text, DescribeRole.Theorem, repoDerived);

    private static DocumentBlock Node(string name, string title, string text, DescribeRole role, bool repoDerived) =>
        Describe.Lean(DescribeId.Create("ideal-graph-" + name.Replace('_', '-').ToLowerInvariant()), DeclarationHandle.Create(Prefix + name),
            H(title), StatementSource.FromLean(),
            repoDerived ? AssessedProvenance.FromRepo(Source) : AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(text))), role);
}
